// Linux recovery and change procedures (reference library). Commands are for
// Debian 12 unless stated (lab hosts: srv01 10.0.20.10, ns1 10.0.10.53,
// rtr01, ws01/ws02); Ubuntu and RHEL differences are given in the steps.

import type { Procedure } from '../types';

export const PROCEDURES_LINUX: Procedure[] = [
  {
    id: 'proc:safe-config-change', title: 'Make a configuration change safely', platform: 'Linux (Debian / Ubuntu / RHEL)',
    services: ['systemd', 'SSH', 'DNS', 'DHCP', 'Firewall', 'Web server', 'Networking'],
    symptoms: ['Service fails to start'],
    purpose: 'The general pattern behind every other procedure: know which file is authoritative, keep a copy you can restore, validate before applying, apply in the least disruptive way, verify from the client\'s point of view, and write down what you did.\n\nMost outages caused by administrators come from skipping one of these steps, not from the change itself.',
    steps: [
      { title: 'Find the file that is really in force', command: 'systemctl cat nginx\nsshd -T | grep -i passwordauthentication\nls -l /etc/resolv.conf', why: 'Edit the source, not a generated copy or a file that is overridden: drop-ins (sshd_config.d, systemd *.d/), generated files (/run, resolv.conf managed by NetworkManager/resolved) and include order decide what is effective.' },
      { title: 'Record the current state', command: 'systemctl status nginx --no-pager\nss -tlnp\ncurl -sI http://srv01.corp.lab/ | head -1', why: 'A baseline lets you prove afterwards that the change (and not something else) altered behaviour, and tells you what "back to normal" looks like.' },
      { title: 'Make a dated backup outside include directories', command: 'mkdir -p /root/backup\ncp -a /etc/nginx/nginx.conf /root/backup/nginx.conf.$(date +%F-%H%M)', why: '`cp -a` keeps owner, mode and timestamps. Keep the copy out of directories that are included by wildcard (sshd_config.d/*.conf, sudoers.d, /etc/netplan/*.yaml, sites-enabled/*), or the backup itself gets loaded.' },
      { title: 'Edit with the safest tool available', command: 'visudo -f /etc/sudoers.d/netops\nsystemctl edit nginx\nnano /etc/nginx/nginx.conf', why: 'Tools like visudo and systemctl edit validate or reload for you. Change one thing at a time so a failure points at one edit.' },
      { title: 'Validate before applying', command: 'nginx -t\nsshd -t\nnamed-checkzone corp.lab /etc/bind/db.corp.lab\nnft -c -f /etc/nftables.conf\nvisudo -c\nnetplan generate\ndhcpd -t -cf /etc/dhcp/dhcpd.conf\nfindmnt --verify', why: 'Every major service has a checker that parses the configuration exactly like the daemon. A failed check costs nothing; a failed restart is an outage.' },
      { title: 'Apply with reload rather than restart where possible', command: 'systemctl reload nginx', why: 'reload re-reads configuration without dropping connections (nginx, sshd, named via rndc, nftables). restart stops the service first: if the new config is broken, the service stays down.' },
      { title: 'Verify functionally, from a client', command: 'curl -sI http://srv01.corp.lab/ | head -1\njournalctl -u nginx -n 20 --no-pager', why: '"active (running)" is not proof the change works. Test what users do, from where users are, and read the log for warnings.' },
      { title: 'Keep or roll back, then record it', command: 'diff /root/backup/nginx.conf.2026-10-19-0910 /etc/nginx/nginx.conf', why: 'If verification fails, restore the backup immediately (proc:rollback) and investigate afterwards. Put the diff, time and result in the ticket (proc:incident-record).' },
    ],
    risks: 'Changes to SSH, firewall, network, PAM or sudo can cut off your own access: use the specific procedures for those (second session open, scheduled rollback, console available). Restarting shared services (DNS, DHCP, the router) affects everyone, not just the host you are working on.',
    verify: 'The validator passes, the service is active, the client-side test that failed before (or the baseline test) succeeds, the journal shows no new errors, and the backup path is written in the ticket.',
  },
  {
    id: 'proc:sshd-safe-restart', title: 'Change sshd configuration without locking yourself out', platform: 'Debian 12 / Ubuntu (ssh.service) · RHEL 9 (sshd.service)',
    services: ['SSH', 'systemd'],
    symptoms: ['Connection refused', 'Login fails', 'Service fails to start'],
    purpose: 'Apply sshd_config changes on a remote server while guaranteeing a way back in.\n\nKey fact: existing SSH sessions are separate sshd processes and survive a reload or restart of the listener. So as long as you keep one session open and test with a NEW connection, a mistake is recoverable.',
    steps: [
      { title: 'Open a spare root session and keep it open', command: 'sudo -i', why: 'If sudo or PAM breaks you still have a root shell. Do not close the session you are working in until a new login has been tested.' },
      { title: 'Back up the files you will change', command: 'mkdir -p /root/backup\ncp -a /etc/ssh/sshd_config.d/10-hardening.conf /root/backup/10-hardening.conf.$(date +%F-%H%M)', why: 'Do not leave the copy in sshd_config.d: a file named *.conf there would be included.' },
      { title: 'Edit, then test the syntax', command: 'nano /etc/ssh/sshd_config.d/10-hardening.conf\nsshd -t && echo CONFIG OK', why: 'No output + exit 0 = valid. Any error names the file and line ("Bad configuration option: ..."). The unit also runs sshd -t as ExecStartPre, but by then the old listener is already gone on restart.' },
      { title: 'Check the effective settings for a real user', command: 'sshd -T -C user=alice,addr=10.0.10.25,host=ws01.corp.lab | grep -E "^(port|listenaddress|passwordauthentication|pubkeyauthentication|permitrootlogin|allowusers|allowgroups) "', why: 'Syntax-valid is not the same as correct: AllowUsers typos, first-value-wins overrides from other drop-ins, and Match blocks only show up here.' },
      { title: 'If the port or listen address changes: open the firewall first', command: 'nft add rule inet filter input tcp dport 2222 accept\n# RHEL with SELinux: semanage port -a -t ssh_port_t -p tcp 2222', why: 'Otherwise sshd listens on a port nobody can reach. Ubuntu 22.10+ uses socket activation: the port is set in ssh.socket, so run `systemctl daemon-reload && systemctl restart ssh.socket` instead of editing Port.' },
      { title: 'Reload (not restart) the daemon', command: 'systemctl reload ssh      # RHEL: systemctl reload sshd', why: 'Reload sends SIGHUP after re-running sshd -t; a broken config is refused and the old one keeps running. Restart is only needed for some changes (e.g. ListenAddress on older versions).' },
      { title: 'Test with a NEW connection from a second terminal', command: 'ssh -v -o ControlMaster=no -o ControlPath=none alice@srv01.corp.lab', why: 'Disabling multiplexing makes sure you are not reusing the existing connection. Confirm "Authenticated to srv01.corp.lab" and that a sudo command works.' },
      { title: 'Read the server log for the test login', command: 'journalctl -u ssh -n 20 --no-pager', why: 'Look for "Accepted publickey for alice" and for warnings such as deprecated options. Refusal reasons are only visible here.' },
      { title: 'If the test fails: roll back from the open session', command: 'cp -a /root/backup/10-hardening.conf.2026-10-19-0910 /etc/ssh/sshd_config.d/10-hardening.conf\nsshd -t && systemctl reload ssh', why: 'Restore, validate, reload, test again. Only then investigate the failed change.' },
    ],
    risks: 'Closing your only session after a bad change (PasswordAuthentication no before keys exist, AllowUsers typo, wrong port) means console access is needed (proc:recover-sshd-console). `systemctl restart ssh` with a broken config leaves no listener: new connections get "Connection refused". Stopping ssh.service on Debian does not kill existing sessions, but `systemctl kill` or a reboot does.',
    verify: '`sshd -t` silent; `systemctl is-active ssh` = active; `ss -tlnp | grep sshd` shows the expected address/port; a brand-new login from a client works and sudo works; journal shows "Accepted publickey".',
  },
  {
    id: 'proc:remote-network-change', title: 'Change network configuration on a remote host with automatic rollback', platform: 'Linux (ifupdown, NetworkManager, networkd)',
    services: ['Networking', 'Routing', 'Firewall', 'SSH'],
    symptoms: ['Connection timed out', 'No route to host', 'No Internet access'],
    purpose: 'Address, gateway, VLAN, bridge and firewall changes can cut the very connection you are using. Before applying them, schedule a job that restores the old configuration in a few minutes; if you can still reach the host afterwards, cancel the job.\n\nThis is the Linux equivalent of "commit confirmed" on network devices.',
    steps: [
      { title: 'Confirm you have an out-of-band path', why: 'Hypervisor console, iDRAC/iLO/IPMI serial-over-LAN, cloud serial console, or someone on site. If none exists, the automatic rollback is your only safety net: make it robust.' },
      { title: 'Work inside tmux or screen', command: 'tmux new -s netchange', why: 'When the SSH connection drops, the shell receives SIGHUP and a half-finished command line (`ifdown eth0; ifup eth0`) is killed between the two halves. Inside tmux it completes.' },
      { title: 'Back up the current configuration', command: 'cp -a /etc/network/interfaces /root/interfaces.$(date +%F-%H%M)\nip -br addr > /root/ip-before.txt; ip route >> /root/ip-before.txt', why: 'The rollback job copies this file back; the ip output documents the working state.' },
      { title: 'Schedule the rollback BEFORE changing anything', command: 'systemd-run --on-active=5min --unit=net-rollback \\\n  /bin/sh -c "cp -a /root/interfaces.2026-10-19-0910 /etc/network/interfaces && ifreload -a"\n# alternative: echo "cp -a /root/interfaces.2026-10-19-0910 /etc/network/interfaces && ifreload -a" | at now + 5 minutes', why: 'systemd-run creates a transient timer (net-rollback.timer) that fires in 5 minutes even if you are disconnected. Use the reload command for your stack: `ifreload -a` (ifupdown2), `systemctl restart networking` (ifupdown), `nmcli connection up ID` (NetworkManager), `networkctl reload` (networkd).' },
      { title: 'Check the job is armed', command: 'systemctl list-timers net-rollback.timer   # or: atq', why: 'A typo in the rollback command is only discovered when you need it. Confirm it is listed with the right time left.' },
      { title: 'Apply the change', command: 'nano /etc/network/interfaces\nifreload -a', why: 'Apply in one step from inside tmux.' },
      { title: 'Reconnect with a new session and test', command: 'ssh alice@srv01.corp.lab\nip -br addr; ip route; ping -c 2 10.0.20.1; getent hosts ns1.corp.lab', why: 'Test from a NEW connection: the old session may survive although new connections fail (or vice versa). Check address, default route, gateway reachability and DNS.' },
      { title: 'Cancel the rollback', command: 'systemctl stop net-rollback.timer   # or: atrm <job-number>', why: 'Only after the new configuration is proven. If you cannot reconnect, do nothing: wait for the timer and reconnect after it fires.' },
    ],
    risks: 'The rollback itself bounces the interface: a second short interruption. If the rollback command is wrong, the host stays unreachable until console access. Changing the default route can also cut traffic for other hosts if this machine is a router. Firewall changes (proc:nft-safe-reload) follow the same pattern.',
    verify: 'A new SSH session works; `ip route` shows the expected default route; the gateway and DNS server answer; services bound to the changed address listen (`ss -tlnp`); `systemctl list-timers` no longer shows the rollback.',
  },
  {
    id: 'proc:netplan-try', title: 'Apply a netplan change with netplan try', platform: 'Ubuntu 20.04+ (netplan, networkd or NetworkManager renderer)',
    services: ['Networking', 'Routing', 'DNS'],
    symptoms: ['No IP address', 'No Internet access', 'Connection timed out'],
    purpose: '`netplan try` applies the new YAML and reverts automatically after a timeout unless you confirm. It is the built-in version of a scheduled rollback.',
    steps: [
      { title: 'Back up the YAML outside /etc/netplan', command: 'cp -a /etc/netplan/01-netcfg.yaml /root/01-netcfg.yaml.$(date +%F-%H%M)', why: 'Every *.yaml in /etc/netplan is applied; a backup there would become live config.' },
      { title: 'Check whether cloud-init owns the network config', command: 'ls /etc/netplan/\ncat /etc/cloud/cloud.cfg.d/99-disable-network-config.cfg 2>/dev/null', why: 'If 50-cloud-init.yaml exists and cloud-init network config is not disabled, your edit may be overwritten at next boot.' },
      { title: 'Edit and validate', command: 'nano /etc/netplan/01-netcfg.yaml\nchmod 600 /etc/netplan/01-netcfg.yaml\nnetplan generate', why: 'generate parses all files and writes backend config to /run without touching interfaces: indentation errors are reported with file:line:column.' },
      { title: 'Review the merged result', command: 'netplan get ethernets.eth0', why: 'Shows the combined effect of all files, including overrides from later-sorting files.' },
      { title: 'Apply with automatic revert', command: 'tmux new -s np\nnetplan try --timeout 120', why: 'Run in tmux so a dropped SSH session does not kill the prompt. If the session freezes, wait: after 120 s the old configuration returns.' },
      { title: 'Test from a second session, then confirm', command: 'ssh alice@10.0.20.10   # from another terminal\n# back in the netplan try terminal: press ENTER', why: 'Pressing ENTER makes it permanent ("Configuration accepted."). Do not confirm on hope: confirm only after a new connection works.' },
      { title: 'Verify the backend state', command: 'networkctl status eth0\nip route\nresolvectl status eth0', why: 'Confirms the address, default route and DNS servers reached the renderer.' },
    ],
    risks: '`netplan apply` has no revert: never use it remotely for risky changes. `netplan try` cannot revert all changes (bond and bridge parameters, some virtual devices) and refuses some configurations; for those use a scheduled rollback (proc:remote-network-change). The revert itself briefly reconfigures the interface.',
    verify: 'New SSH connection works; `ip -br addr` and `ip route` match the YAML; DNS resolves (`resolvectl query srv01.corp.lab`); after a reboot (in a maintenance window) the same state returns.',
  },
  {
    id: 'proc:nm-reconnect', title: 'Apply or re-apply a NetworkManager connection', platform: 'RHEL 9 / Fedora / Ubuntu & Debian desktop (NetworkManager)',
    services: ['Networking', 'DHCP', 'DNS', 'IPv6'],
    symptoms: ['No IP address', 'No Internet access', 'Name resolution fails'],
    purpose: 'Change a NetworkManager profile and make the running interface use it, or recover an interface stuck without an address, with as little disruption as possible.',
    steps: [
      { title: 'See which profile is active on which device', command: 'nmcli device status\nnmcli connection show --active', why: 'Profile names ("System eth0", "Wired connection 1") differ from device names; you modify the profile, not the device.' },
      { title: 'Record the current settings', command: 'nmcli -f ipv4.method,ipv4.addresses,ipv4.gateway,ipv4.dns,ipv4.ignore-auto-dns connection show "System eth0" > /root/nm-eth0.$(date +%F-%H%M).txt\ncp -a /etc/NetworkManager/system-connections/ /root/nm-backup.$(date +%F-%H%M)', why: 'Keyfiles are the persistent source; the text file is a readable record for the rollback.' },
      { title: 'Schedule a rollback when working remotely', command: 'systemd-run --on-active=5min --unit=nm-rollback /bin/sh -c "cp -a /root/nm-backup.2026-10-19-0910/. /etc/NetworkManager/system-connections/ && nmcli connection reload && nmcli connection up \'System eth0\'"', why: 'nmcli has no built-in confirm/revert. (On RHEL, `nmstatectl apply --no-commit --timeout 300` followed by `nmstatectl commit` gives a native checkpoint with automatic rollback.)' },
      { title: 'Modify the profile', command: 'nmcli connection modify "System eth0" ipv4.method manual ipv4.addresses 10.0.20.10/24 ipv4.gateway 10.0.20.1 ipv4.dns 10.0.10.53 ipv4.dns-search corp.lab', why: 'This only writes the keyfile. For DHCP with your own DNS server also set `ipv4.ignore-auto-dns yes`, otherwise the DHCP-supplied servers are used too.' },
      { title: 'Apply to the device', command: 'nmcli device reapply eth0\n# if reapply is not enough: nmcli connection up "System eth0"', why: 'reapply changes the running device in place where possible; `connection up` fully re-activates (brief link down, new DHCP exchange). Run it inside tmux remotely.' },
      { title: 'For a stuck DHCP device, re-activate and watch', command: 'nmcli connection up "System eth0"\njournalctl -u NetworkManager -n 30 --no-pager | grep -i dhcp', why: 'The log shows "dhcp4 (eth0): state changed" lines; a timeout means no DHCPOFFER came back (link, VLAN, DHCP server).' },
      { title: 'Verify and cancel the rollback', command: 'nmcli device show eth0 | grep -E "IP4|DNS"\nip route\nsystemctl stop nm-rollback.timer', why: 'Cancel only after a new SSH connection and name resolution work.' },
    ],
    risks: '`nmcli connection down` on the interface carrying SSH disconnects you immediately (and `up` never runs unless both are on one line in tmux). Hand-edited keyfiles with the wrong mode (not 600 root) are ignored silently. If NetworkManager manages /etc/resolv.conf, editing that file directly is overwritten.',
    verify: '`nmcli device status` shows connected with the expected profile; `ip -br addr`/`ip route` match; `getent hosts srv01.corp.lab` resolves; a new remote session works.',
  },
  {
    id: 'proc:networkd-reconfigure', title: 'Reload systemd-networkd configuration', platform: 'Linux with systemd-networkd (Ubuntu Server, minimal/cloud images)',
    services: ['Networking', 'systemd', 'DHCP', 'IPv6'],
    symptoms: ['No IP address', 'No Internet access'],
    purpose: 'Apply changes to .network/.netdev files for systemd-networkd, or re-run configuration on a link that ended up degraded or failed. On Ubuntu, if the files are generated by netplan, change the YAML and use proc:netplan-try instead.',
    steps: [
      { title: 'Find out who generates the files', command: 'networkctl status eth0 | grep "Network File"\nls /etc/systemd/network/ /run/systemd/network/', why: 'Files in /run/systemd/network come from netplan and are regenerated: edit /etc/netplan. Files in /etc/systemd/network are yours.' },
      { title: 'Back up and edit', command: 'cp -a /etc/systemd/network/10-eth0.network /root/10-eth0.network.$(date +%F-%H%M)\nnano /etc/systemd/network/10-eth0.network', why: 'Keep the backup outside the directory: networkd loads every *.network file it finds there.' },
      { title: 'Schedule a rollback (remote hosts)', command: 'systemd-run --on-active=5min --unit=networkd-rollback /bin/sh -c "cp -a /root/10-eth0.network.2026-10-19-0910 /etc/systemd/network/10-eth0.network && networkctl reload && networkctl reconfigure eth0"', why: 'networkd has no try/confirm mode of its own.' },
      { title: 'Reload and reconfigure', command: 'networkctl reload\nnetworkctl reconfigure eth0', why: '`reload` re-reads files and applies changed ones; `reconfigure` forces the link to drop and re-apply its configuration (systemd 244+).' },
      { title: 'Check state and logs', command: 'networkctl list\nnetworkctl status eth0\njournalctl -u systemd-networkd -n 30 --no-pager', why: 'Expect OPERATIONAL routable and SETUP configured. "unmanaged" = no .network file matched ([Match] Name= wrong); "degraded" = no global address (DHCP or static address missing).' },
      { title: 'Cancel the rollback after testing a new connection', command: 'systemctl stop networkd-rollback.timer', why: 'Only after a new SSH login and a test to the gateway and DNS succeed.' },
    ],
    risks: 'reconfigure removes and re-adds addresses on the link: your SSH session may drop. A .network file that matches too broadly (Name=e*) can reconfigure interfaces you did not intend. Never edit /run/systemd/network by hand.',
    verify: '`networkctl list` shows the link routable/configured; `ip route` has the default route; `resolvectl status eth0` lists the expected DNS servers; a new SSH session works.',
  },
  {
    id: 'proc:dns-resolver-fix', title: 'Fix client name resolution at its source', platform: 'Linux (static resolv.conf, systemd-resolved, NetworkManager)',
    services: ['DNS', 'Networking'],
    symptoms: ['Name resolution fails', 'No Internet access'],
    purpose: 'Find why a Linux host cannot resolve names, decide whether the problem is the client configuration or the DNS server, and fix it in the component that owns /etc/resolv.conf so the fix survives reboots and DHCP renewals.',
    steps: [
      { title: 'Reproduce as the application sees it', command: 'getent hosts srv01.corp.lab\nping -c1 srv01.corp.lab', why: 'getent follows nsswitch.conf (/etc/hosts, then DNS) exactly like ssh and curl. "Temporary failure in name resolution" = no server answered; "Name or service not known" = an answer said the name does not exist.' },
      { title: 'Ask the DNS server directly', command: 'dig srv01.corp.lab\ndig @10.0.10.53 srv01.corp.lab', why: 'If the direct query to the known-good server works but the default one fails, the client points at the wrong/unreachable server. If both return NXDOMAIN/SERVFAIL, the server or zone is the problem (proc:bind-zone-change).' },
      { title: 'Check overrides before DNS', command: 'grep -v "^#" /etc/hosts\ngrep ^hosts /etc/nsswitch.conf', why: 'An old /etc/hosts entry beats correct DNS; a hosts line without `dns` never asks DNS.' },
      { title: 'Find out who owns /etc/resolv.conf', command: 'ls -l /etc/resolv.conf\nhead -3 /etc/resolv.conf\nresolvectl status 2>/dev/null | head -20', why: 'Symlink to ../run/systemd/resolve/stub-resolv.conf = systemd-resolved; "# Generated by NetworkManager" = NetworkManager; "Generated by resolvconf" = resolvconf (ifupdown dns-nameservers); otherwise a static file.' },
      { title: 'Fix: static file (Debian server, the lab)', command: 'cp -a /etc/resolv.conf /root/resolv.conf.$(date +%F-%H%M)\nprintf "search corp.lab\\nnameserver 10.0.10.53\\n" > /etc/resolv.conf', why: 'Here the file IS the configuration. Check that DHCP (dhclient) is not also rewriting it.' },
      { title: 'Fix: systemd-resolved (Ubuntu)', command: '# set DNS in the netplan YAML (nameservers: addresses: [10.0.10.53]) then\nnetplan try\nresolvectl flush-caches\nresolvectl status eth0', why: 'The stub file only contains 127.0.0.53; the upstream servers come per link from netplan/networkd/DHCP. Global fallback: DNS= in /etc/systemd/resolved.conf, then `systemctl restart systemd-resolved`.' },
      { title: 'Fix: NetworkManager (RHEL, desktops)', command: 'nmcli connection modify "System eth0" ipv4.dns 10.0.10.53 ipv4.ignore-auto-dns yes ipv4.dns-search corp.lab\nnmcli device reapply eth0', why: 'NetworkManager rewrites resolv.conf from the profile; editing the file is undone at the next lease or reconnect.' },
      { title: 'Verify, then remove workarounds', command: 'getent hosts srv01.corp.lab\ndig +short srv01.corp.lab', why: 'Remove temporary /etc/hosts entries or `chattr +i /etc/resolv.conf` hacks: they hide future DNS changes and turn into the next incident.' },
    ],
    risks: 'Restarting systemd-resolved or NetworkManager briefly interrupts resolution (and NetworkManager may bounce interfaces). Pointing clients at a public resolver "to make it work" breaks internal names (corp.lab, AD SRV records): a workaround, not a fix.',
    verify: '`getent hosts` and `dig` agree and return the expected address; the setting survives `systemctl restart` of the manager (or a DHCP renewal); short names resolve via the search domain.',
  },
  {
    id: 'proc:nft-safe-reload', title: 'Reload nftables rules with an automatic rollback', platform: 'Debian 12 / Ubuntu (nftables.service)',
    services: ['Firewall', 'NAT', 'SSH'],
    symptoms: ['Connection timed out', 'Connection refused', 'No route to host'],
    purpose: 'Load a changed /etc/nftables.conf on a remote host without risking a permanent lockout.\n\nTrap: your current SSH session usually survives a bad ruleset because `ct state established,related accept` still matches it, so "I am still connected" proves nothing. Always test with a NEW connection.',
    steps: [
      { title: 'Save the running ruleset as a rollback file', command: '{ echo "flush ruleset"; nft list ruleset; } > /root/nft-rollback.$(date +%F-%H%M).nft\ncp -a /etc/nftables.conf /root/nftables.conf.$(date +%F-%H%M)', why: 'The running rules may differ from the file (live `nft add rule` changes). A listing has no "flush ruleset", so add it: otherwise loading it would duplicate rules instead of replacing them.' },
      { title: 'Edit and check the new file', command: 'nano /etc/nftables.conf\nnft -c -f /etc/nftables.conf && echo SYNTAX OK', why: '-c parses and validates against the kernel without applying anything. Confirm the file still has `ct state established,related accept`, `iif "lo" accept` and your SSH accept rule.' },
      { title: 'Arm the rollback', command: 'systemd-run --on-active=3min --unit=nft-rollback /usr/sbin/nft -f /root/nft-rollback.2026-10-19-0910.nft\nsystemctl list-timers nft-rollback.timer', why: 'If the new rules cut you off, the previous ruleset returns in 3 minutes without you. (Alternative: `echo "nft -f /root/nft-rollback...nft" | at now + 3 minutes`.)' },
      { title: 'Apply atomically', command: 'systemctl reload nftables', why: 'On Debian ExecReload runs `nft -f /etc/nftables.conf`; with `flush ruleset` at the top the whole file is swapped in one transaction (all or nothing).' },
      { title: 'Test new connections from outside', command: 'nc -zv -w 3 srv01.corp.lab 22      # from ws01\nssh -o ControlMaster=no -o ControlPath=none alice@srv01.corp.lab', why: 'A new TCP handshake must pass the rules; also test every service the change was meant to affect (and one it should block).' },
      { title: 'Watch counters and drops', command: 'nft list chain inet filter input\njournalctl -k -n 20 --no-pager', why: 'Counters on rules (if configured) and log rules show what is being hit; a growing policy-drop counter with your traffic means a missing accept.' },
      { title: 'Cancel the rollback and make sure it persists', command: 'systemctl stop nft-rollback.timer\nsystemctl is-enabled nftables', why: 'Only after the new connection works. "disabled" means the rules will not be loaded at boot.' },
    ],
    risks: '`nft flush ruleset` typed by hand removes all filtering (and NAT on a router) immediately. On a router, a mistake cuts every client, not only you. The rollback restores the ruleset, not conntrack state; existing NATed connections may still reset. Docker, libvirt and fail2ban add their own tables: `flush ruleset` in the file removes them until those services re-add their rules (restart them).',
    verify: 'New SSH connections succeed; intended services are reachable and blocked ones time out or are refused as designed; `nft list ruleset` matches the file; the timer is gone; `systemctl is-enabled nftables` is enabled.',
  },
  {
    id: 'proc:systemd-unit-failed', title: 'Diagnose and recover a failed systemd unit', platform: 'Linux (systemd)',
    services: ['systemd', 'SSH', 'DNS', 'DHCP', 'Web server', 'Firewall'],
    symptoms: ['Service fails to start', 'Connection refused'],
    purpose: 'Find out why a unit is in the failed state, fix the cause (usually configuration, permissions, port conflicts or dependencies) and bring it back, layer by layer.',
    steps: [
      { title: 'List failed units', command: 'systemctl --failed', why: 'Several failures often share one cause (network-online, a mount, DNS). Start with the one others depend on.' },
      { title: 'Read the status', command: 'systemctl status nginx --no-pager -l', why: 'Look at Loaded (path, enabled, drop-ins), Active (Result: exit-code/timeout/signal/start-limit-hit), which Process line failed (ExecStartPre vs ExecStart) and its status code.' },
      { title: 'Read the full log for the unit', command: 'journalctl -xeu nginx --no-pager | tail -40', why: 'The daemon\'s own message (file and line, "Address already in use", "Permission denied") is usually just above the systemd "Failed with result" line.' },
      { title: 'See the unit definition actually used', command: 'systemctl cat nginx', why: 'Shows the vendor file plus every drop-in. A drop-in with a second ExecStart= or a wrong User= is a common self-inflicted failure.' },
      { title: 'Run the validator or the command by hand', command: 'nginx -t\nsshd -t\nnamed-checkconf\nnft -c -f /etc/nftables.conf', why: 'Reproduces the failure with the full error text, without systemd in the way.' },
      { title: 'Check the usual environmental causes', command: 'ss -tlnp | grep ":80 "\ndf -h / /var\nls -l /etc/nginx/nginx.conf', why: 'Port already in use, disk full, missing or unreadable file, missing dependency (`systemctl list-dependencies nginx`).' },
      { title: 'Fix, reload units if you changed one, clear the failure', command: 'systemctl daemon-reload\nsystemctl reset-failed nginx', why: 'daemon-reload is needed after editing unit files by hand. reset-failed clears "start-limit-hit" ("Start request repeated too quickly."), otherwise systemd refuses to start it.' },
      { title: 'Start and verify, check boot enablement', command: 'systemctl start nginx\nsystemctl is-active nginx; systemctl is-enabled nginx', why: 'A unit that works now but is "disabled" will be down again after the next reboot.' },
    ],
    risks: 'Restarting dependent units (networking, nftables, named) affects other services and remote access. `systemctl unmask` or `enable` on a unit someone deliberately masked/disabled may undo a decision: check the ticket history. "Unit X could not be found" usually means a wrong name (ssh vs sshd, named vs bind9) rather than a missing package.',
    verify: '`systemctl is-active UNIT` = active, no new errors in `journalctl -u UNIT -b`, the service answers on its port from a client, and `systemctl --failed` is empty.',
  },
  {
    id: 'proc:recover-sshd-console', title: 'Recover SSH access from the console', platform: 'Debian 12 / Ubuntu / RHEL 9',
    services: ['SSH', 'Firewall', 'Networking', 'systemd'],
    symptoms: ['Connection refused', 'Connection timed out', 'Login fails', 'Permission denied'],
    purpose: 'When nobody can SSH in any more (sshd not starting, firewall lockout, wrong network config, broken PAM/keys), use out-of-band access to find and undo the cause.\n\nPreparation matters: a console is only useful if a local account with a known password (or root password) exists.',
    steps: [
      { title: 'Get console access', why: 'Hypervisor console (Proxmox/VMware/Hyper-V), BMC (iDRAC, iLO, IPMI SOL), cloud serial console, or a physical keyboard. Log in as root or a local sudo user (not a directory account if DNS/AD may be part of the problem).' },
      { title: 'Is sshd running and listening?', command: 'systemctl status ssh --no-pager     # RHEL: sshd\nss -tlnp | grep sshd', why: 'No listener = clients get "Connection refused" (or timeouts if a firewall drops first).' },
      { title: 'If it failed: read why and test the config', command: 'journalctl -u ssh -b -n 30 --no-pager\nsshd -t', why: 'The journal names the file and line, or "no hostkeys available". Restore the backup or fix the line, then `systemctl restart ssh`. Missing host keys: `ssh-keygen -A`.' },
      { title: 'Is the network up?', command: 'ip -br addr\nip route\nping -c 2 10.0.20.1', why: 'A failed network change leaves no address or no default route: restore the interface config from the backup and re-apply (ifreload -a / netplan apply / nmcli connection up).' },
      { title: 'Is the firewall dropping SSH?', command: 'nft list ruleset | grep -n -E "policy|dport 22"\n# emergency, temporary: nft insert rule inet filter input tcp dport 22 accept', why: 'An inserted rule takes effect immediately and is lost at the next reload/reboot: fix /etc/nftables.conf properly afterwards (proc:nft-safe-reload).' },
      { title: 'Authentication problems: watch a live attempt', command: 'journalctl -u ssh -f\n# or a one-shot debug server on another port:\n/usr/sbin/sshd -d -p 2222', why: 'The server-side reason (bad modes on ~/.ssh, AllowUsers, PAM account denial, nologin) is only logged on the server. sshd -d prints every step for one connection (open port 2222 in the firewall temporarily, then stop it).' },
      { title: 'No usable password: boot to rescue mode', command: '# GRUB: press e, append to the linux line:\nsystemd.unit=rescue.target\n# or, last resort:\ninit=/bin/bash   then: mount -o remount,rw /', why: 'Rescue target asks for the root password (Debian/RHEL); `init=/bin/bash` does not but bypasses everything: reset the password (`passwd`), then `exec /sbin/init` or reboot. Encrypted disks still need the passphrase.' },
      { title: 'Test from a client, then document', command: 'ssh -v alice@srv01.corp.lab', why: 'Confirm from a normal client, remove temporary rules and debug listeners, and write the incident record (proc:incident-record), including why the change was not tested safely.' },
    ],
    risks: 'init=/bin/bash and rescue mode bypass normal security and must be logged. Rebooting a production server to reach GRUB causes downtime. Temporary firewall rules and debug sshd instances left behind are security holes.',
    verify: 'A new SSH login from a normal client works with the intended authentication method; `sshd -t` is silent; the persistent configuration (not just a temporary fix) is correct, so it survives a reboot.',
  },
  {
    id: 'proc:bind-zone-change', title: 'Change a BIND zone safely', platform: 'Debian 12 (bind9 / named.service) · RHEL 9 (named)',
    services: ['DNS'],
    symptoms: ['Name resolution fails'],
    purpose: 'Add or change records in a static BIND zone so that the primary loads it, secondaries pick it up and clients see it, without breaking the zone.',
    steps: [
      { title: 'Back up the zone file', command: 'cp -a /etc/bind/db.corp.lab /root/db.corp.lab.$(date +%F-%H%M)', why: 'Keeps owner (root:bind) and mode for an exact restore.' },
      { title: 'Check the zone type', command: 'grep -A4 \'zone "corp.lab"\' /etc/bind/named.conf.local', why: 'If the zone allows dynamic updates (allow-update/update-policy), run `rndc freeze corp.lab` before editing and `rndc thaw corp.lab` after; otherwise the journal (.jnl) and your edit conflict.' },
      { title: 'Edit and INCREASE THE SERIAL', command: 'nano /etc/bind/db.corp.lab\n#   2026101901 -> 2026101902', why: 'Secondaries only transfer a zone whose serial is higher. Date-based YYYYMMDDnn makes this obvious. Remember the trailing dot on fully qualified names.' },
      { title: 'Validate', command: 'named-checkzone corp.lab /etc/bind/db.corp.lab\nnamed-checkconf', why: 'Must print "loaded serial 2026101902" and "OK". On error, named would keep serving the old zone (reload) or nothing (restart).' },
      { title: 'Reload only that zone', command: 'rndc reload corp.lab', why: 'Reloads one zone without restarting named: other zones and the resolver cache are untouched.' },
      { title: 'Confirm the load in the log', command: 'journalctl -u named -n 20 --no-pager | grep corp.lab', why: '"zone corp.lab/IN: loaded serial 2026101902" (and "sending notifies") confirms it. Errors here mean the old data is still served.' },
      { title: 'Query the server and the secondaries', command: 'dig @10.0.10.53 corp.lab SOA +short\ndig @10.0.10.53 srv02.corp.lab +short', why: 'The SOA shows the new serial; query each secondary the same way to confirm transfer.' },
      { title: 'Allow for caching', command: 'dig srv01.corp.lab | grep -A1 "ANSWER SECTION"', why: 'Resolvers and clients keep old answers for the record TTL (negative answers for the SOA minimum). For planned address changes, lower the TTL a day ahead.' },
    ],
    risks: '`systemctl restart named` with a broken zone or config stops DNS for every client. Rolling back by restoring the old file restores the OLD serial: secondaries ignore it. When rolling back, use the old content with a NEW, higher serial. Deleting NS or glue records can make the whole zone unresolvable.',
    verify: 'named-checkzone OK; the log shows the new serial loaded; `dig @primary` and `dig @secondary` return the new data and the same serial; clients resolve it after the TTL.',
  },
  {
    id: 'proc:dhcp-renew', title: 'Renew a DHCP lease and trace the exchange', platform: 'Linux client (dhclient, NetworkManager, networkd) · ISC DHCP server',
    services: ['DHCP', 'Networking'],
    symptoms: ['No IP address', 'No Internet access', 'Name resolution fails'],
    purpose: 'Get a fresh lease on a Linux client, and when that fails, find out at which DHCP step (DISCOVER, OFFER, REQUEST, ACK) the exchange stops.',
    steps: [
      { title: 'Look at the current state', command: 'ip -br addr show eth0\nip route\ncat /var/lib/dhcp/dhclient.eth0.leases 2>/dev/null | tail -15', why: 'A 169.254.x.x address or none at all means no lease; the client lease file shows server, router and DNS options of the last lease.' },
      { title: 'Renew: dhclient (Debian ifupdown, the lab ws02)', command: 'dhclient -r eth0; dhclient -v eth0', why: '-r releases (the address disappears: run both on ONE line, inside tmux if remote). -v prints DHCPDISCOVER/DHCPOFFER/DHCPREQUEST/DHCPACK.' },
      { title: 'Renew: NetworkManager or networkd', command: 'nmcli connection up "Wired connection 1"\n# systemd-networkd:\nnetworkctl renew eth0', why: 'Use the tool that manages the interface; running dhclient by hand alongside NetworkManager creates a second, conflicting client.' },
      { title: 'If there is no offer: capture on the client', command: 'tcpdump -i eth0 -n -e port 67 or port 68', why: 'Only DISCOVERs leaving = no server reachable on this segment: link, VLAN access port, or a missing relay on the router (the server sits in another subnet).' },
      { title: 'Check the server side', command: 'journalctl -u isc-dhcp-server -n 30 --no-pager', why: '"DHCPDISCOVER from 52:54:00:d4:00:42 via eth0: network 10.0.10.0/24: no free leases" = pool exhausted; no DISCOVER at all = packets do not arrive; "No subnet declaration for eth0" = wrong interface/subnet in dhcpd.conf.' },
      { title: 'Check what the client was given', command: 'ip route\ncat /etc/resolv.conf', why: 'A lease with a wrong `option routers` or DNS gives an address but no Internet or name resolution: fix dhcpd.conf, restart the server, renew again.' },
    ],
    risks: 'Releasing the lease on a remote host disconnects you. Restarting isc-dhcp-server is safe for existing leases (they are in dhcpd.leases) but a syntax error stops it: run `dhcpd -t` first. Deleting dhcpd.leases causes duplicate addresses.',
    verify: 'The client has an address in the expected range, the right default gateway and DNS server; `ping -c2 10.0.10.1` and `getent hosts srv01.corp.lab` work; the server log shows DHCPACK for the client MAC.',
  },
  {
    id: 'proc:incident-record', title: 'Write an incident record', platform: 'Any platform',
    services: ['SSH', 'DNS', 'DHCP', 'Firewall', 'Networking', 'systemd'],
    symptoms: [],
    purpose: 'Keep a factual record of an outage or failed change while it happens, so others can take over, the fix can be verified, and the same incident does not repeat.\n\nStart it at the first sign of trouble, not afterwards from memory.',
    steps: [
      { title: 'Open the record with UTC timestamps', command: 'date -u +%FT%TZ', why: 'Logs on different hosts and time zones only line up in UTC. Note who is working on it and where (ticket, channel).' },
      { title: 'Use a fixed template', command: 'Title:            ssh to srv01 refused after hardening change\nStatus:           open | mitigated | resolved\nImpact:           who/what was affected, from when to when (UTC)\nDetection:        how it was noticed (user report, monitoring)\nTimeline:         HH:MMZ  event / command / result (one line each)\nEvidence:         exact commands and outputs, log lines\nRoot cause:       the underlying cause, not just the trigger\nWorkaround:       what restored service temporarily\nPermanent fix:    the change that removes the cause\nVerification:     test that proves it is fixed\nRollback:         backup paths / how to undo\nFollow-up:        actions, owner, due date\nLessons:          what would have prevented or shortened it', why: 'A template forces the questions people forget under pressure (impact, verification, follow-up).' },
      { title: 'Log actions as you take them', command: '09:12Z  journalctl -u ssh -n 5 -> "line 6: Bad configuration option: PubkeyAuthentcation"\n09:14Z  restored /root/backup/10-hardening.conf.2026-10-19-0840, sshd -t OK, systemctl restart ssh\n09:15Z  new login from ws01 OK', why: 'Every change during an incident is another variable. Recording command and result lets you undo steps and explains the final state.' },
      { title: 'Separate trigger, root cause, workaround and fix', why: 'Trigger: the change that made it visible (restart after edit). Root cause: why it could happen (edit without sshd -t, no second-session test). Workaround: restores service (restore backup). Permanent fix: removes the cause (correct config plus a validated change procedure). A ticket closed on a workaround reopens later.' },
      { title: 'Define follow-up actions with owners', why: 'Examples: add `sshd -t` to the change checklist, monitor the SSH port, document the console access path, lower DNS TTLs before migrations. Without an owner and date nothing happens.' },
      { title: 'Review blamelessly', why: 'Ask what made the mistake easy (missing validation, no rollback, unclear ownership of a file) rather than who made it; people then report problems early.' },
    ],
    risks: 'Records written from memory afterwards get times and order wrong. Pasting secrets (passwords, private keys, tokens) into tickets: redact them.',
    verify: 'Someone who was not involved can read the record and understand impact, cause, what was changed, how to undo it, and what is still open.',
  },
  {
    id: 'proc:rollback', title: 'Roll back a failed change', platform: 'Linux (Debian / Ubuntu / RHEL)',
    services: ['systemd', 'SSH', 'DNS', 'DHCP', 'Firewall', 'Networking', 'Web server'],
    symptoms: ['Service fails to start', 'Connection refused', 'Login fails'],
    purpose: 'Return a system to its last known-good state quickly when a change fails verification, instead of debugging forward during an outage. Decide the rollback trigger before the change ("if the new login test fails, or after 15 minutes, roll back").',
    steps: [
      { title: 'Declare the rollback and stop changing things', why: 'Record the time and the reason in the incident record. Further "quick fixes" make the state harder to restore.' },
      { title: 'Restore the configuration from the dated backup', command: 'cp -a /root/backup/nginx.conf.2026-10-19-0910 /etc/nginx/nginx.conf\n# whole-directory changes (etckeeper): cd /etc && git log --oneline -3 && git checkout HEAD~1 -- nginx/', why: '`cp -a` restores owner and mode as well as content. Restore every file the change touched (including drop-ins you created: delete those).' },
      { title: 'Validate the restored configuration', command: 'nginx -t', why: 'The backup may predate another legitimate change; validate before applying, as for any change.' },
      { title: 'Apply it in the least disruptive way', command: 'systemctl reload nginx\n# unit file changes: systemctl daemon-reload first', why: 'Same rules as the forward change: reload where possible, scheduled rollback/console for network and firewall.' },
      { title: 'Package rollback when an upgrade caused it', command: 'apt-cache policy nginx\napt install nginx=1.22.1-9   # RHEL: dnf history undo <id>', why: 'Pin the version (`apt-mark hold nginx`) until the problem is understood, so the next unattended upgrade does not reapply it.' },
      { title: 'Mind state that must not go backwards', why: 'DNS zone serials must still increase (restore old content with a NEW serial). DHCP lease files, databases and application data changed since the backup must not be overwritten blindly. VM snapshots roll back everything, including logs and data written since.' },
      { title: 'Verify and record', command: 'systemctl is-active nginx\ncurl -sI http://srv01.corp.lab/ | head -1', why: 'Run the same verification as for the original change, then record the rollback and plan the corrected change (with its own test) separately.' },
    ],
    risks: 'A rollback is itself a change: it can fail, and restarting services causes a brief interruption. Restoring files without their permissions (plain `cp` or editors) creates new failures (sshd StrictModes, sudoers 440). Snapshot rollbacks lose data written after the snapshot.',
    verify: 'Service behaviour matches the baseline recorded before the change; validators pass; the journal is clean; the incident record lists what was restored and from which backup.',
  },
  {
    id: 'proc:tls-diagnose', title: 'Diagnose an HTTPS certificate error', platform: 'Any client · Linux server (nginx)',
    services: ['TLS', 'Web server'],
    symptoms: ['Certificate not trusted', 'Certificate expired', 'Name mismatch'],
    purpose: 'Turn a browser warning or a curl (60) error into a precise cause: expired, wrong name, missing intermediate, untrusted root, or a server that did not load its new files.',
    steps: [
      { title: 'Reproduce with a verifying client', command: 'curl -v -I https://www.corp.lab/', why: 'The last lines give the exact check that failed. Never add -k while diagnosing: it hides the error.' },
      { title: 'See what the server sends', command: 'openssl s_client -connect www.corp.lab:443 -servername www.corp.lab </dev/null', why: 'Count the certificates under "Certificate chain"; read the depth of each "verify error" and the final "Verify return code".' },
      { title: 'Read the served certificate', command: 'openssl s_client -connect www.corp.lab:443 </dev/null 2>/dev/null | openssl x509 -noout -subject -issuer -dates -ext subjectAltName', why: 'Dates (expired?), names (does the SAN list the name users type?), issuer (which CA?).' },
      { title: 'Compare with the files on the server', command: 'openssl x509 -in /etc/ssl/certs/www.corp.lab.crt -noout -subject -enddate\ngrep -c BEGIN /etc/ssl/certs/www.corp.lab.crt\nnginx -t', why: 'Different from what is served → nginx did not load the files (failed reload). One certificate in the file → missing intermediate.' },
      { title: 'Check the client side when only some clients fail', command: 'ls /usr/local/share/ca-certificates/\ndate', why: 'Missing internal root, or a wrong clock.' },
    ],
    risks: 'Read-only. The fixes (new files, reload) are covered by proc:tls-renewal.',
    verify: 'You can name the failing check (chain, dates, name, key) and the component to fix (server files, server reload, client trust store, client clock).',
  },
  {
    id: 'proc:tls-renewal', title: 'Renew and install a server certificate safely', platform: 'Linux · nginx (similar for Apache/HAProxy)',
    services: ['TLS', 'Web server'],
    symptoms: ['Certificate expired'],
    purpose: 'Replace a certificate (and usually its key) without an outage and confirm clients see the new one.',
    steps: [
      { title: 'Check the new files belong together', command: 'openssl x509 -in new.crt -noout -subject -enddate -ext subjectAltName\nopenssl x509 -in new.crt -noout -modulus | openssl md5\nopenssl rsa -in new.key -noout -modulus | openssl md5', why: 'Right names, new date, and identical modulus hashes.' },
      { title: 'Make sure the chain is complete', command: 'grep -c BEGIN new.crt\nopenssl verify -untrusted new.crt new.crt', why: 'At least 2 certificates (leaf + intermediate). If you received cert.pem and chain.pem: cat cert.pem chain.pem > fullchain.pem (never cat into an input file).' },
      { title: 'Back up and install', command: 'cp -a /etc/ssl/certs/www.corp.lab.crt /root/www.corp.lab.crt.bak\ncp -a /etc/ssl/private/www.corp.lab.key /root/www.corp.lab.key.bak\ncp new.crt /etc/ssl/certs/www.corp.lab.crt\ncp new.key /etc/ssl/private/www.corp.lab.key\nchmod 640 /etc/ssl/private/www.corp.lab.key', why: 'Install certificate AND key together; keep the key unreadable for other users.' },
      { title: 'Test and reload', command: 'nginx -t && systemctl reload nginx', why: 'If nginx -t fails, do not reload: fix or roll back. A failed reload keeps serving the old certificate.' },
      { title: 'Verify from outside', command: 'openssl s_client -connect www.corp.lab:443 </dev/null 2>/dev/null | openssl x509 -noout -enddate\ncurl -I https://www.corp.lab/', why: 'The served notAfter must be the new date and curl must verify without -k.' },
    ],
    risks: 'Installing a key that does not match makes the next restart or reboot fail (outage). Restarting instead of reloading drops connections. Never email private keys.',
    verify: 'Served certificate shows the new expiry; `nginx -t` succeeds; monitoring (checkend) is green; the change is recorded with the next renewal date.',
  },
  {
    id: 'proc:mtu-diagnose', title: 'Diagnose "small things work, large transfers hang"', platform: 'Linux (ping, tracepath, tcpdump) · any router',
    services: ['Networking', 'Routing'],
    symptoms: ['Large transfers hang', 'Connection timed out'],
    purpose: 'Confirm an MTU problem, find the link responsible, and choose between correcting MTUs, allowing ICMP and MSS clamping.',
    steps: [
      { title: 'Prove it is size-related', command: 'curl -I URL\ncurl -m 20 -o /dev/null URL', why: 'Headers arrive, the body does not ("0 out of N bytes received"): only large packets are lost.' },
      { title: 'Find the largest packet that passes', command: 'ping -c 1 -M do -s 1472 DST\nping -c 1 -M do -s 1400 DST', why: '"Frag needed and DF set (mtu = N)" names the bottleneck; silence for large sizes only means they vanish without ICMP (mismatch or black hole). Path MTU = largest size + 28.' },
      { title: 'Locate the link', command: 'tracepath -n DST\nip link show', why: 'Where pmtu drops; then compare the MTU on BOTH ends of that link (including switches for jumbo frames and tunnel interfaces).' },
      { title: 'Check ICMP filtering', command: 'nft list ruleset | grep -n -e icmp -e related', why: 'ICMP type 3 (IPv4) and ICMPv6 type 2 must reach the senders; "ct state established,related accept" first.' },
      { title: 'Fix', command: 'ip link set dev eth2 mtu 1500   # and persist it\nnft add rule inet filter forward oifname "eth2" tcp flags syn tcp option maxseg size set rt mtu', why: 'Mismatch → make both ends equal. Legitimately smaller link (PPPoE, VPN) → MSS clamping on that router, and allow ICMP.' },
    ],
    risks: 'Changing the MTU of the interface you are connected through can stall your session; use the console. Clamping helps TCP only.',
    verify: 'A full download and an HTTPS handshake complete; ping -M do -s 1472 passes (or reports the documented MTU); the configuration survives a reboot.',
  },
];
